package me.zenith.skypvp.listener;
import me.zenith.skypvp.ZenithSkyPvP; import org.bukkit.entity.Player; import org.bukkit.event.*; import org.bukkit.event.entity.PlayerDeathEvent; import org.bukkit.event.player.PlayerJoinEvent; import org.bukkit.event.player.PlayerQuitEvent;
public class GameListener implements Listener {private final ZenithSkyPvP p; public GameListener(ZenithSkyPvP p){this.p=p;} @EventHandler public void join(PlayerJoinEvent e){p.getServer().getScheduler().runTaskLater(p,()->{if(p.spawn().has())e.getPlayer().teleport(p.spawn().get());},2L);} @EventHandler public void death(PlayerDeathEvent e){Player v=e.getEntity();p.data().death(v.getUniqueId()); if(v.getKiller()!=null){p.data().kill(v.getKiller().getUniqueId()); v.getKiller().sendMessage("§a+"+p.getConfig().getInt("coins.kill-reward",25)+" coins for the kill!");}p.data().save();} @EventHandler public void quit(PlayerQuitEvent e){}}
